import trimesh, numpy as np
from shapely.geometry import Polygon
for name, path, zc in [("box","exports/model.box.e1af9484.stl",30.8),("lid","exports/model.lid.6029fe16.stl",3.4)]:
    m = trimesh.load(path)
    xs = {"box":[-29.5,-24,-19,-5.84+0.1,0,5.8],"lid":[-17,-12,-7]}
    print("==",name)
    for x in xs[name]:
        sec = m.section(plane_origin=[x,0,0], plane_normal=[1,0,0])
        if sec is None: print(x,"none"); continue
        # entities loops in 3D (plane coords Y,Z); find loop containing bore center
        for e in sec.entities:
            pts = sec.vertices[e.points][:,1:]  # Y,Z
            if len(pts) < 3: continue
            try: poly = Polygon(pts)
            except: continue
            if poly.area < 1: continue
            if poly.contains(trimesh.points.Point([-30.5, zc])) if False else True:
                pass
            c = poly.centroid
            dist = np.hypot(c.x+30.5, c.y-zc)
            if dist < 2.0:
                print(f" x={x} loop n={len(pts)} area={poly.area:.3f} deq={2*np.sqrt(poly.area/np.pi):.3f} yb=({pts[:,0].min():.2f},{pts[:,0].max():.2f}) zb=({pts[:,1].min():.2f},{pts[:,1].max():.2f})")
